            if (count($candidates) > 1) {
                throw new RuntimeException('Ambiguous runtime input for '.$name.'.');
            }
            $slot = $candidates[0] ?? null;

            if ($slot === null && $parameter->getType() === null) {
                $slot = array_keys($inputs)[$position] ?? null;
            }
